using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading.Tasks;
using Mmorpg.Runtime;
using Mmorpg.Domain;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
public static class InspectHumanoidStatesR8
{
 const string E="Docs/Validation/HumanoidStatesR8/",Raw="Temp/HumanoidR8/Captures/";
 static ActorHealth Player=>UnityEngine.Object.FindAnyObjectByType<JourneySession>().Player;
 static ProductionSpriteAnimator Animator=>Player.GetComponent<ProductionSpriteAnimator>();
 static ProductionCharacterStates States=>Player.GetComponent<ProductionCharacterStates>();
 static SwordSwing Sword=>Player.GetComponent<SwordSwing>();
 static Rigidbody2D Rb=>Player.GetComponent<Rigidbody2D>();
 static OfflineAuthority Authority=>UnityEngine.Object.FindAnyObjectByType<OfflineAuthority>();
 static SpriteRenderer Blade=>Player.GetComponentsInChildren<SpriteRenderer>(true).Single(r=>r.name=="EquippedSword");
 static Keyboard Keys=>InputSystem.devices.OfType<Keyboard>().Single(k=>k.name=="AnimationKeyboard");
 static Mouse Mouse=>InputSystem.devices.OfType<Mouse>().Single(k=>k.name=="AnimationMouse");
 static void Check(bool b,string message){if(!b)throw new Exception(message+" state="+Animator.State+" hp="+Player.State.Health);}
 static void Input(params Key[] keys)=>InputSystem.QueueStateEvent(Keys,new KeyboardState(keys));
 static void Aim(Vector2 v,int buttons=0)=>InputSystem.QueueStateEvent(Mouse,new MouseState{position=Camera.main.WorldToScreenPoint((Vector2)Player.transform.position+v*3),buttons=(ushort)buttons});
 static Key[] Move(int d){var v=ProductionDirections.Vector(d);var list=new List<Key>();if(v.x<0)list.Add(Key.A);if(v.x>0)list.Add(Key.D);if(v.y<0)list.Add(Key.S);if(v.y>0)list.Add(Key.W);return list.ToArray();}
 static async Task Wait(float seconds){double end=Time.timeAsDouble+seconds;while(Time.timeAsDouble<end)await Task.Delay(5);}
 static async Task Tap(Key key){Input(key);await Wait(.012f);Input();}
 static async Task Reset(int d=0){Input();Aim(Vector2.down);var preview=Player.GetComponent<WeaponValidationPreview>();if(preview!=null&&preview.BowSelected)preview.SelectSword();while(Sword.Busy)await Wait(.02f);Player.Configure(Faction.Player);Rb.simulated=true;Rb.position=new Vector2(-2.75f,0);Rb.linearVelocity=Vector2.zero;await Wait(.06f);Input(Move(d));await Wait(.08f);Input();await Wait(.13f);Check(Animator.DirectionIndex==d,"Facing setup");}
 // Post-spatial-validation path of the real authority. Training fixture only, never client damage values.
 static bool Hit(ActionStrike strike=ActionStrike.Wolf,bool friendly=false){var attacker=friendly?Player:UnityEngine.Object.FindAnyObjectByType<TrainingDummy>().Health;return (bool)typeof(OfflineAuthority).GetMethod("ResolveDamage",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(Authority,new object[]{attacker,Player,strike,null});}
 public sealed class Row{public string state,source,sprite;public int frame,direction,hp,reactions;public double time,dodgeUntil;public float speed,x,y,alpha,grip;public bool dodging,blade,attack,simulated,complete,visible;public float[] pivot,canvas,screenRoot;}
 static Dictionary<string,JToken> bounds;
 static bool Visible(){
  if(bounds==null){bounds=new Dictionary<string,JToken>();foreach(string a in new[]{"dodge","death"}){var m=JObject.Parse(File.ReadAllText("ArtSource/Labs/Humanoid2026/R8/"+a+"/manifest.json"));int i=0;foreach(var f in m["frames"])bounds[a+"pose_"+(i++).ToString("000")]=f;}}
  if(!bounds.TryGetValue(Animator.State+Animator.Body.sprite.name,out var row))return true;var b=row["alphaBounds"];float px=(float)row["pivotTop"][0],py=(float)row["pivotTop"][1];foreach(int xi in new[]{0,2})foreach(int yi in new[]{1,3}){var point=Animator.Body.transform.TransformPoint(new Vector2(((float)b[xi]-px)/32,(py-(float)b[yi])/32));var q=Camera.main.WorldToScreenPoint(point);if(q.x<0||q.y<0||q.x>Screen.width||q.y>Screen.height)return false;}return true;
 }
 static async Task<List<Row>> Trace(string name,float duration,bool capture=true){
  var rows=new List<Row>();var done=new TaskCompletionSource<bool>();var weapon=Sword;int postMortemSweepSamples=0;Action<Vector2,Vector2> onSample=(a,b)=>{if(!Player.State.IsAlive)postMortemSweepSamples++;};weapon.SweepSampled+=onSample;
  try{Player.StartCoroutine(Record(name,duration,capture,rows,done));if(await Task.WhenAny(done.Task,Task.Delay(45000))!=done.Task)throw new Exception("Trace stalled "+name);await done.Task;Check(postMortemSweepSamples==0,"Sweep after confirmed death");File.WriteAllText(E+name+".json",JsonConvert.SerializeObject(rows));File.WriteAllText(E+name+"-summary.json",JsonConvert.SerializeObject(new{postMortemSweepSamples,renderedFrames=rows.Count,timeScale=Time.timeScale}));return rows;}
  finally{if(weapon!=null)weapon.SweepSampled-=onSample;}
 }

 static System.Collections.IEnumerator Record(string name,float seconds,bool capture,List<Row> rows,TaskCompletionSource<bool> done){
  Directory.CreateDirectory(Raw);double end=Time.timeAsDouble+seconds,next=-1;string last="";int index=0;
  while(Time.timeAsDouble<end){yield return new WaitForEndOfFrame();try{var q=Camera.main.WorldToScreenPoint(Player.transform.position);var sp=Animator.Body.sprite;var row=new Row{state=Animator.State,source=Animator.CurrentFrame.source,sprite=sp.name,frame=Time.frameCount,time=Time.timeAsDouble,direction=Animator.DirectionIndex,hp=Player.State.Health,reactions=States.ConfirmedReactions,dodgeUntil=Player.State.DodgeUntil,speed=Rb.linearVelocity.magnitude,x=Rb.position.x,y=Rb.position.y,alpha=Animator.Body.color.a,dodging=Player.State.IsDodging(Time.timeAsDouble),blade=Blade.enabled&&Blade.gameObject.activeInHierarchy,attack=Sword.Busy,simulated=Rb.simulated,complete=States.DeathComplete,grip=Vector3.Distance(Sword.GripWorld,Animator.Body.transform.TransformPoint(Animator.CurrentFrame.hand)),pivot=new[]{sp.pivot.x,sp.pivot.y},canvas=new[]{sp.rect.width,sp.rect.height},screenRoot=new[]{q.x,Screen.height-q.y},visible=Visible()};rows.Add(row);
   if(capture&&(row.sprite!=last||Time.timeAsDouble>=next)){var tex=ScreenCapture.CaptureScreenshotAsTexture();string path=Raw+name+"-"+(index++).ToString("000")+".png";File.WriteAllBytes(path,tex.EncodeToPNG());UnityEngine.Object.Destroy(tex);File.AppendAllText(E+"captures.jsonl",JsonConvert.SerializeObject(new{name,path,row,screen=new[]{Screen.width,Screen.height},timeScale=Time.timeScale})+"\n");last=row.sprite;next=Time.timeAsDouble+.15;}
  }catch(Exception ex){done.SetException(ex);yield break;}}done.SetResult(true);
 }
 public static async Task<string> Dodges(){var result=new List<object>();var dummy=UnityEngine.Object.FindAnyObjectByType<TrainingDummy>();var old=dummy.transform.position;dummy.transform.position=new Vector3(25,25);Time.timeScale=.35f;try{for(int d=0;d<8;d++){
  await Reset(d);Vector2 v=ProductionDirections.Vector(d);Aim(-v);if(d%2==1){Input(Move(d));await Wait(.08f);}Input(Move(d).Concat(new[]{Key.Space}).ToArray());await Wait(.006f);Check(Player.State.IsDodging(Time.timeAsDouble),"Dodge refused");int reactions=States.ConfirmedReactions;Check(!Hit(),"Damage accepted during dodge");Input(d%2==0?new Key[0]:Move(d));var rows=await Trace("dodge-"+d,.36f);Input();var active=rows.Where(r=>r.dodging).ToArray();Check(active.Length>0&&active.All(r=>r.state=="dodge"&&r.direction==d),"Dodge direction/priority");Check(active.Select(r=>r.sprite).Distinct().Count()==8,"Missing dodge poses");Check(active.Max(r=>r.speed)>8.9&&active.Max(r=>r.speed)<9.01,"Dodge speed");Check(active.All(r=>r.grip<.0001&&r.blade&&r.visible),"Dodge hand/screen framing");Check(States.ConfirmedReactions==reactions,"Rejected damage reacted");double until=Player.State.DodgeUntil;await Tap(Key.Space);var denied=await Trace("dodge-cooldown-"+d,.08f,false);Check(Player.State.DodgeUntil==until&&denied.All(r=>!r.dodging),"Dodge cooldown changed");Check(rows.Any(r=>r.state==(d%2==0?"idle":"walk")),"Dodge return transition");result.Add(new{direction=d,poses=8,seconds=CombatRules.DodgeDuration,speed=active.Max(r=>r.speed),cooldownRejected=true,immune=true,handAligned=true,visible=true});
 }Time.timeScale=1;await Reset(0);Input(Key.Space);await Wait(.012f);Input();var normal=await Trace("dodge-normal-speed",.4f,false);Check(normal.Any(r=>r.dodging)&&normal.All(r=>!r.dodging||r.state=="dodge"),"Normal cadence dodge");await Wait(.1f);Aim(Vector2.down,1);await Wait(.02f);Aim(Vector2.down);var post=await Trace("dodge-to-attack",.4f);Check(post.Any(r=>r.state.StartsWith("attack")),"Dodge to permitted attack");File.WriteAllText(E+"dodge-results.json",JsonConvert.SerializeObject(result,Formatting.Indented));return "8/8 dodge orientations, cooldown, immunity, grip, transitions and normal cadence passed";}finally{Input();Aim(Vector2.down);Time.timeScale=1;dummy.transform.position=old;}}
 public static async Task<string> Hurt(){var result=new List<object>();Time.timeScale=.6f;try{for(int d=0;d<8;d++){
  await Reset(d);if(d%2==1)Input(Move(d));int before=States.ConfirmedReactions,hp=Player.State.Health;Check(Hit(),"Incoming hit refused");Check(!Hit()&&!Hit(friendly:true),"Immune/friendly hit accepted");var rows=await Trace("hurt-"+d,.5f);Input();Check(States.ConfirmedReactions==before+1&&Player.State.Health==hp-15,"Hurt count/damage");Check(rows.Any(r=>r.state=="hurt"&&r.direction==d),"Hurt orientation");result.Add(new{direction=d,accepted=true,immuneRejected=true,friendlyRejected=true,singleReaction=true});
 }await Reset();Aim(Vector2.down,1);await Wait(.02f);Aim(Vector2.down);Check(Sword.Busy&&Hit(),"Attack/Hurt fixture");var deferred=await Trace("attack-to-hurt",.85f);Check(deferred.Any(r=>r.state=="hurt")&&deferred.Where(r=>r.attack).All(r=>r.state.StartsWith("attack")),"Deferred Hurt interrupted strike");File.WriteAllText(E+"hurt-results.json",JsonConvert.SerializeObject(result));return "Hurt reused in 8 views, accepted/rejected damage and deferred attack reaction passed";}finally{Input();Aim(Vector2.down);Time.timeScale=1;}}
 static async Task Prelethal(){while(Player.State.Health>28){Check(Hit(ActionStrike.Golem),"Prelethal hit refused");await Wait(.36f);}}
 public static async Task<string> Deaths(int start=0,int count=4){var result=new List<object>();Time.timeScale=1;try{for(int d=start;d<start+count;d++){
  await Reset(d);await Prelethal();if(d%3==1)Input(Move(d));if(d%3==2){Aim(ProductionDirections.Vector(d),1);await Wait(.025f);Aim(ProductionDirections.Vector(d));}int reactions=States.ConfirmedReactions;Check(Hit(ActionStrike.Golem)&&!Player.State.IsAlive,"Lethal hit refused");Vector2 at=Rb.position;Input(Key.D);Aim(Vector2.right,1);var rows=await Trace("death-"+d,2.95f);Input();Aim(Vector2.down);Check(rows.Skip(1).All(r=>r.state=="death"&&r.direction==d&&!r.blade&&!r.attack&&!r.simulated&&r.alpha>.99&&r.visible),"Death state/frame/visibility");Check(rows.Where(r=>r.state=="death").Select(r=>r.sprite).Distinct().Count()==25,"Incomplete fall");Check(rows.Last().complete&&rows.TakeLast(5).Select(r=>r.sprite).Distinct().Count()==1,"Terminal not held");Check(rows.All(r=>Vector2.Distance(at,new Vector2(r.x,r.y))<.001),"Death moved physical root");Check(States.ConfirmedReactions==reactions&&!Authority.RequestAttack(Player,Vector2.right)&&!Authority.RequestDodge(Player),"Dead authority/Hurt priority");result.Add(new{direction=d,poses=25,terminalHeld=true,bladeHidden=true,logicalRootStable=true,visible=true});
 }File.WriteAllText(E+"death-results-"+start+".json",JsonConvert.SerializeObject(result));return "Death directions "+start+".."+(start+count-1)+" passed";}finally{Input();Aim(Vector2.down);Time.timeScale=1;}}
 public static async Task<string> DeferredHurtToDeath(){await Reset();await Prelethal();Aim(Vector2.down,2);await Wait(.03f);Aim(Vector2.down);Check(Hit(),"Deferred prelethal wolf hit");var rows=await Trace("heavy-to-hurt",.72f);Check(Player.State.Health==1&&rows.Any(r=>r.state=="hurt"),"Deferred Hurt setup");Check(Hit(ActionStrike.Golem),"Hurt-to-death authority refused");var death=await Trace("hurt-to-death",2.7f);Check(death.All(r=>r.state=="death"),"Lethal played Hurt first");return "Valid deferred Hurt to lethal death; no immunity bypass";}
 public static async Task<string> Restart(){var identity=LocalJourneyProfile.IdentityId;await Trace("death-before-restart",.15f);await Tap(Key.F5);await Wait(.7f);Check(Player.State.IsAlive&&Animator.State=="idle"&&Animator.enabled&&Player.GetComponent<PlayerController>().enabled&&Sword.enabled&&Rb.simulated&&Blade.enabled,"Restart did not restore actor");Check(identity==LocalJourneyProfile.IdentityId&&!Player.GetComponent<WeaponValidationPreview>().BowSelected,"Restart changed identity/equipment");await Trace("restart-to-idle",.25f);File.WriteAllText(E+"restart.json",JsonConvert.SerializeObject(new{passed=true,identityPreserved=true,alive=true,controlsRestored=true}));return "Death to F5 restart restored idle, controls, sword and isolated identity";}
 static async Task RealWait(float seconds){double end=Time.realtimeSinceStartupAsDouble+seconds;while(Time.realtimeSinceStartupAsDouble<end)await Task.Delay(5);}
 static async Task MenuTap(){Input(Key.Escape);await RealWait(.03f);Input();await RealWait(.04f);}
 static async Task Click(string name){var b=UnityEngine.Object.FindObjectsByType<UnityEngine.UI.Button>().Single(x=>x.name==name&&x.gameObject.activeInHierarchy);var r=(RectTransform)b.transform;var corners=new Vector3[4];r.GetWorldCorners(corners);Vector2 p=(corners[0]+corners[2])*.5f;InputSystem.QueueStateEvent(Mouse,new MouseState{position=p});await RealWait(.03f);InputSystem.QueueStateEvent(Mouse,new MouseState{position=p,buttons=1});await RealWait(.03f);InputSystem.QueueStateEvent(Mouse,new MouseState{position=p});await RealWait(.05f);}
 static async Task BowMenu(int view){await MenuTap();Check(Time.timeScale==0,"Esc pause");await Click("ValidateWeapons");await Click(view==0?"WeaponBowSouth":"WeaponBowEast");await Click("WeaponTest");Check(Player.GetComponent<WeaponValidationPreview>().BowSelected,"Bow menu selection");}
 public static async Task<string> BowStates(){var report=new List<object>();try{for(int view=0;view<2;view++){
  await Reset();await BowMenu(view);int d=view==0?0:3;await Tap(Key.J);Check(Player.GetComponent<WeaponValidationPreview>().Playing,"Bow J playback");await Tap(Key.V);Check(Player.GetComponent<WeaponValidationPreview>().ViewIndex==1-view,"Bow V");await Tap(Key.V);await Tap(Key.J);await MenuTap();int pose=Player.GetComponent<WeaponValidationPreview>().PoseIndex;await RealWait(.15f);Check(Player.GetComponent<WeaponValidationPreview>().PoseIndex==pose,"Paused bow advanced");await MenuTap();Check(Hit(),"Bow incoming hit");Check(!Player.GetComponent<WeaponValidationPreview>().BowSelected&&Animator.enabled&&Sword.enabled,"Damage stranded bow components");var hurt=await Trace("bow-hurt-"+view,.45f);Check(hurt.Any(r=>r.state=="hurt"&&r.direction==d),"Bow Hurt facing mismatch");
  await Reset();await Prelethal();await BowMenu(view);await Tap(Key.J);int reactions=States.ConfirmedReactions;Check(Hit(ActionStrike.Golem)&&!Player.State.IsAlive,"Bow lethal fixture");Check(!Player.GetComponent<WeaponValidationPreview>().BowSelected&&Animator.enabled,"Death stranded bow");var death=await Trace("bow-death-"+view,2.8f);Check(death.All(r=>r.state=="death"&&r.direction==d&&!r.blade&&r.alpha>.99&&r.visible)&&States.ConfirmedReactions==reactions,"Bow death priority/facing/fade");var target=(Transform)typeof(CameraFollow).GetField("target",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(Camera.main.GetComponent<CameraFollow>());Check(target.name=="StatesCameraFocus","Camera target not restored");await Restart();int before=States.ConfirmedReactions;Check(Hit(),"Reload hit refused");await Wait(.05f);Check(States.ConfirmedReactions==before+1,"Reload duplicated callback");report.Add(new{view,hurt=true,death=true,facing=d,paused=true,cameraRestored=true,restart=true,singleCallback=true});
 }File.WriteAllText(E+"bow-states.json",JsonConvert.SerializeObject(report));return "Bow frontal/lateral, V/J/Esc, real Hurt/death, camera and reload compatibility passed";}finally{Input();Aim(Vector2.down);Time.timeScale=1;}}
 public static async Task<string> LoadOfficial(){Time.timeScale=1;UnityEngine.SceneManagement.SceneManager.LoadScene("Assets/Mmorpg/Scenes/MmorpgWorld.unity");await RealWait(.7f);Check(LocalJourneyProfile.Root.Contains("Temp")&&Sword.OriginPolicy==SwordSwing.SweepOriginPolicy.LegacyGrip,"Legacy isolation/policy");Directory.CreateDirectory(E+"legacy-official");UnityEditor.SessionState.SetString("b11-evidence",E+"legacy-official/");return "Official loaded with isolated Temp profile; legacy presentation unchanged";}
 public static async Task<string> LegacyMenu(){Check(UnityEngine.Object.FindAnyObjectByType<WeaponValidationMenu>(FindObjectsInactive.Include)==null,"Experimental page entered official scene");await MenuTap();Check(Time.timeScale==0,"Official Esc failed");await Click("Continuar");Check(Time.timeScale==1,"Official continue failed");File.WriteAllText(E+"legacy-menu.json","{\"passed\":true,\"experimentalPageAbsent\":true,\"legacyPolicyPreserved\":true}");return "Official menu normal, no experimental page";}
 public static async Task<string> Transitions(){Time.timeScale=.5f;try{
  await Reset(3);Aim(Vector2.left);Input(Key.D);var moving=Trace("walk-dodge-walk",.9f);await Wait(.18f);Input(Key.D,Key.Space);await Wait(.015f);Input(Key.D);var rows=await moving;Input();Check(rows.TakeWhile(r=>r.state!="dodge").Any(r=>r.state=="walk")&&rows.Any(r=>r.state=="dodge")&&rows.Last().state=="walk","Walk/Dodge/Walk");
  await Reset(0);var idle=Trace("idle-dodge-idle-attack",1);await Wait(.08f);Input(Key.Space);await Wait(.012f);Input();Check(!Authority.RequestAttack(Player,Vector2.down),"Attack accepted during dodge");await Wait(.25f);Aim(Vector2.down,1);await Wait(.012f);Aim(Vector2.down);rows=await idle;Check(rows.Any(r=>r.state=="idle")&&rows.Any(r=>r.state=="dodge")&&rows.Any(r=>r.state.StartsWith("attack")),"Dodge/Attack transition");
  await Reset(1);await Prelethal();Input(Key.A);var walk=Trace("walk-to-death",2.9f);await Wait(.12f);Check(Hit(ActionStrike.Golem),"Walk lethal");rows=await walk;Input();Check(rows.Any(r=>r.state=="walk")&&rows.Any(r=>r.state=="death"),"Walk/Death transition");
  await Reset(3);await Prelethal();Aim(Vector2.right,2);await Wait(.012f);Aim(Vector2.right);var attack=Trace("attack-to-death",2.9f);await Wait(.1f);Check(Hit(ActionStrike.Golem),"Attack lethal");rows=await attack;Check(rows.Any(r=>r.state.StartsWith("attack"))&&rows.SkipWhile(r=>r.hp>0).All(r=>r.state=="death")&&rows.SkipWhile(r=>r.hp>0).Skip(1).All(r=>!r.attack),"Attack/Death transition");File.WriteAllText(E+"transitions.json","{\"walkDodgeWalk\":true,\"idleDodgeAttack\":true,\"walkDeath\":true,\"attackDeath\":true,\"attackDuringDodgeRejected\":true}");return "Continuous allowed transitions recorded; prohibited dodge attack refused";
 }finally{Input();Aim(Vector2.down);Time.timeScale=1;}}
}
